import {copyCurveKeys,pasteCurveKeys,parseCurveClipboard,curveClipboardMaxText} from './curve-clipboard.js';
export function curveSelectionRows(timeline,selection,trackId,multi=false){const rows=[];for(const track of timeline.tracks){if(!multi&&track.id!==trackId)continue;const indices=[];for(let i=0;i<track.keys.length;i++)if(selection.has(track.keys[i]))indices.push(i);if(indices.length)rows.push({track,indices});}return rows;}
export function copyCurveGroup(rows){const origin=Math.min(...rows.map(r=>r.track.keys[r.indices[0]].time)),value={format:'hb.curve.group',version:1,tracks:rows.map(({track,indices})=>({id:track.id,name:track.name,offset:track.keys[indices[0]].time-origin,clipboard:copyCurveKeys(track,indices)}))};return parseCurveGroup(JSON.stringify(value));}
export function parseCurveGroup(text){if(typeof text!=='string'||text.length>curveClipboardMaxText)throw Error('곡선 클립보드 크기를 확인하세요.');let value;try{value=JSON.parse(text);}catch{throw Error('곡선 클립보드 JSON을 확인하세요.');}if(!value||value.format!=='hb.curve.group'||value.version!==1||!Array.isArray(value.tracks)||!value.tracks.length||Object.keys(value).some(k=>!['format','version','tracks'].includes(k)))throw Error('다중 곡선 클립보드 형식을 확인하세요.');const ids=new Set();for(const row of value.tracks){if(!row||typeof row.id!=='string'||!row.id||row.id.length>200||ids.has(row.id)||typeof row.name!=='string'||row.name.length>80||!Number.isFinite(row.offset)||row.offset<0||row.offset>86400||Object.keys(row).some(k=>!['id','name','offset','clipboard'].includes(k)))throw Error('복사한 곡선의 대상과 상대 시각을 확인하세요.');ids.add(row.id);parseCurveClipboard(JSON.stringify(row.clipboard));}return value;}
export function pasteCurveGroup(timeline,value,time,{maxKeys=128}={}){const group=parseCurveGroup(JSON.stringify(value)),used=new Set(),rows=[];for(const row of group.tracks){let track=timeline.tracks.find(t=>t.id===row.id);if(!track){const matches=timeline.tracks.filter(t=>t.name===row.name&&t.type===row.clipboard.type);if(matches.length===1)track=matches[0];}if(!track||used.has(track.id))throw Error('붙여넣을 곡선 ID 또는 같은 이름·자료형의 고유 대상을 확인하세요.');used.add(track.id);rows.push({id:track.id,...pasteCurveKeys(track,row.clipboard,time+row.offset,{length:timeline.length,maxKeys})});}return rows;}
